def transform(grid):
    g=[row[:] for row in grid]
    counts=Counter(x for row in g for x in row if x != 0)
    marker=min(counts, key=counts.get)
    pts=[(r,c) for r,row in enumerate(g) for c,x in enumerate(row) if x==marker]
    r0=min(r for r,c in pts); c0=min(c for r,c in pts)
    shape={(r-r0,c-c0) for r,c in pts}
    h=max(r for r,c in shape)+1; w=max(c for r,c in shape)+1
    for r in range(len(g)-h+1):
        for c in range(len(g[0])-w+1):
            if all(g[r+dr][c+dc]==0 for dr,dc in shape):
                for dr,dc in shape: g[r+dr][c+dc]=marker
    return g
